### 🌐 Live Weather Map with Hourly Forecast Slider

Below is a self-contained HTML file that you can open in any modern web browser. It will display an interactive map with weather overlays and a slider to navigate through hourly forecasts.

**Note:** You'll need to replace `'YOUR_API_KEY'` with your actual OpenWeatherMap API key.

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <title>Channelview Weather Map</title>
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <!-- Leaflet CSS -->
  <link
    rel="stylesheet"
    href="https://unpkg.com/leaflet@1.7.1/dist/leaflet.css"
  />
  <style>
    #map {
      height: 90vh;
      width: 100%;
    }
    #slider-container {
      position: absolute;
      top: 10px;
      left: 50%;
      transform: translateX(-50%);
      z-index: 1000;
      background: white;
      padding: 10px;
      border-radius: 5px;
    }
    #hour-label {
      margin-top: 5px;
      text-align: center;
    }
  </style>
</head>
<body>
  <div id="slider-container">
    <input
      type="range"
      id="hour-slider"
      min="0"
      max="23"
      value="0"
      step="1"
    />
    <div id="hour-label">Hour: 0</div>
  </div>
  <div id="map"></div>

  <!-- Leaflet JS -->
  <script
    src="https://unpkg.com/leaflet@1.7.1/dist/leaflet.js"
  ></script>
  <script>
    // Initialize the map
    const map = L.map('map').setView([29.7848, -95.1149], 12);

    // Add OpenStreetMap tiles
    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
      attribution:
        '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors',
    }).addTo(map);

    // Add a circle with a 5-mile radius (~8047 meters)
    const radiusInMeters = 8047;
    const circle = L.circle([29.7848, -95.1149], {
      color: 'blue',
      fillColor: '#blue',
      fillOpacity: 0.1,
      radius: radiusInMeters,
    }).addTo(map);

    // Placeholder for weather data
    let weatherData = [];

    // Function to fetch weather data
    async function fetchWeatherData() {
      const apiKey = 'YOUR_API_KEY'; // Replace with your OpenWeatherMap API key
      const lat = 29.7848;
      const lon = -95.1149;
      const url = `https://api.openweathermap.org/data/2.5/onecall?lat=${lat}&lon=${lon}&exclude=current,minutely,daily,alerts&units=imperial&appid=${apiKey}`;

      try {
        const response = await fetch(url);
        const data = await response.json();
        weatherData = data.hourly;
        updateWeatherOverlay(0);
      } catch (error) {
        console.error('Error fetching weather data:', error);
      }
    }

    // Function to update weather overlay based on selected hour
    function updateWeatherOverlay(hourIndex) {
      if (!weatherData.length) return;

      const hourData = weatherData[hourIndex];
      const description = hourData.weather[0].description;
      const temp = hourData.temp;
      const pop = hourData.pop * 100; // Probability of precipitation

      // Remove existing popup if any
      if (map.hasLayer(popup)) {
        map.removeLayer(popup);
      }

      // Create a popup with weather info
      popup = L.popup()
        .setLatLng([29.7848, -95.1149])
        .setContent(
          `<b>Hour ${hourIndex}</b><br>Condition: ${description}<br>Temp: ${temp}°F<br>Precipitation: ${pop}%`
        )
        .openOn(map);
    }

    // Initialize popup variable
    let popup;

    // Event listener for slider
    const slider = document.getElementById('hour-slider');
    const hourLabel = document.getElementById('hour-label');
    slider.addEventListener('input', (e) => {
      const hour = e.target.value;
      hourLabel.textContent = `Hour: ${hour}`;
      updateWeatherOverlay(hour);
    });

    // Fetch weather data on load
    fetchWeatherData();
  </script>
</body>
</html>
```

